def gen(rng):
    def fmt(n, par, relabel=True):
        # par[i] is the parent of node i (i >= 1), with par[i] < i
        lab = list(range(n))
        if relabel:
            rest = lab[1:]
            rng.shuffle(rest)
            lab = [0] + rest
        edges = []
        for i in range(1, n):
            a, b = lab[par[i]], lab[i]
            if rng.random() < 0.5:
                a, b = b, a
            edges.append((a, b))
        if relabel:
            rng.shuffle(edges)
        return str(n) + ''.join(f'\n{a} {b}' for a, b in edges)
    def leaves_of(n, par):
        has = [False] * n
        for i in range(1, n):
            has[par[i]] = True
        return n - sum(has)
    def rand_par(n, depthcap=None, maxleaves=None):
        while True:
            par = [0] * n
            depth = [1] * n
            for i in range(1, n):
                while True:
                    p = rng.randrange(max(0, i - rng.choice((1, 2, 3, i))), i)
                    if depthcap is None or depth[p] < depthcap:
                        break
                par[i] = p
                depth[i] = depth[p] + 1
            if maxleaves is None or leaves_of(n, par) <= maxleaves:
                return par
    tests = ['1', fmt(2, [0, 0]), fmt(3, [0, 0, 0]), fmt(3, [0, 0, 1]), fmt(5, [0, 0, 0, 1, 1], False), fmt(4, [0, 0, 1, 2], False),
             fmt(6, [0, 0, 0, 0, 0, 0], False)]
    for n in (4, 5, 6, 7, 8, 9, 10, 12, 14):
        for _ in range(2):
            tests.append(fmt(n, rand_par(n, None, 5)))
    for n in (120, 300, 1000):
        tests.append(fmt(n, rand_par(n)))
    N = 100000
    # star
    tests.append(fmt(N, [0] * N))
    # random tree
    tests.append(fmt(N, [0] + [rng.randrange(0, i) for i in range(1, N)]))
    # caterpillar: spine of 4900 nodes, each with extra leaves hanging off it
    par = [0] * N
    for i in range(1, N):
        if i < 4900:
            par[i] = i - 1
        else:
            par[i] = rng.randrange(0, 4900)
    tests.append(fmt(N, par))
    # complete binary tree
    tests.append(fmt(N, [0] + [(i - 1) // 2 for i in range(1, N)]))
    # random tree with a long spine and bushy bottom
    par = [0] * N
    for i in range(1, N):
        if i < 4900:
            par[i] = i - 1
        else:
            par[i] = rng.randrange(max(0, i - 50), i) if rng.random() < 0.5 else rng.randrange(0, i)
    d = [1] * N
    for i in range(1, N):
        d[i] = d[par[i]] + 1
    if max(d) <= 5000:
        tests.append(fmt(N, par))
    # path of 5000 plus a big star at the end
    par = [0] * N
    for i in range(1, N):
        par[i] = i - 1 if i < 4990 else 4989
    tests.append(fmt(N, par))
    return tests
